// EP01 "Never Move Grandpa", full episode (113.3 s, 97 shots): loader / entry module.
//
//   node tools/render.js engine/episodes/ep01/index.js <out> [times=...]       render this module directly, or
//   node tools/render.js episodes/ep01/timeline.json <out> [times=...]         through the timeline (episodes/ep01/ep01.js)
//
// Shots, times and every storyboard decision live in episodes/ep01/timeline.json (generated by
// episodes/ep01/tools/make_board.py; board: episodes/ep01/board.md). Each timeline entry names its builder (`shot`) and the
// part module that owns it (`params.builder_part`, default `params.part`). The five parts are animated in parallel:
//   part1.js s01-s24 (approved test builders + the world montage), part2.js s25-s41, part3.js s42-s57,
//   part4.js s58-s76 (s61-s63 reuse part1's fb_* builders: the callback), part5.js s77-s97.
// Routing: builder key -> partN.builders[key]; a key the part has not written yet renders as a labelled placeholder
// (common.js stubBuilder), so the full timeline always renders end to end. A key claimed by two parts is an error.
import * as sets from '../../kit/sets.js';
import * as P1 from './part1.js';
import * as P2 from './part2.js';
import * as P3 from './part3.js';
import * as P4 from './part4.js';
import * as P5 from './part5.js';
import { stubBuilder } from './common.js';

const TL = await (await fetch(new URL('../../../episodes/ep01/timeline.json', import.meta.url))).json();
const PARTS = { 1: P1, 2: P2, 3: P3, 4: P4, 5: P5 };

// builder key -> { part, built }
export const routing = {};
for (const e of TL.shots) {
  const key = e.shot || e.name; const part = (e.params && (e.params.builder_part ?? e.params.part)) || 0;
  if (!PARTS[part]) throw new Error(`ep01: shot ${e.name} (${key}) has no valid part (${part})`);
  if (routing[key] && routing[key].part !== part) throw new Error(`ep01: builder "${key}" is claimed by part ${routing[key].part} and part ${part}`);
  routing[key] = { part, built: !!(PARTS[part].builders && PARTS[part].builders[key]) };
}
// A builder a part defines but no timeline shot uses is almost always a typo in its key: say so.
for (const [n, P] of Object.entries(PARTS)) for (const k of Object.keys(P.builders || {})) {
  if (!routing[k]) console.warn(`ep01: part${n}.js defines builder "${k}" but no timeline shot uses it`);
  else if (routing[k].part !== +n) console.warn(`ep01: part${n}.js defines "${k}", which the timeline routes to part${routing[k].part}.js`);
}
export const builders = Object.fromEntries(Object.entries(routing).map(([k, r]) => [k, r.built ? PARTS[r.part].builders[k] : stubBuilder(k, r.part, false)]));
export const progress = Object.fromEntries([1, 2, 3, 4, 5].map((n) => {
  const keys = Object.entries(routing).filter(([, r]) => r.part === n); return [n, { built: keys.filter(([, r]) => r.built).length, total: keys.length }];
}));

export default {
  name: 'ep01', fps: TL.fps, width: TL.width || 1080, height: TL.height || 1920, seed: 'ep01', duration: TL.duration,
  quality: { shadows: 'off' },
  post: sets.postPreset('night'),
  async setup(ctx) { for (const P of Object.values(PARTS)) if (typeof P.setup === 'function') await P.setup(ctx); },
  shots: TL.shots.map((e) => ({ name: e.name, start: e.start, end: e.end, params: e.params, ...builders[e.shot || e.name] })),
};
export { TL as timeline };
